L19:       const m = /^(>=|<=|>|<|=)?(\d+\.\d+\.\d+)$/.exec(part);
L20:       if (!m) return false;
L21:       const c = cmp(version, m[2]!);
L22:       switch (m[1] ?? "=") {
L23:         case ">=":
L24:           return c >= 0;
L25:         case "<=":
L26:           return c <= 0;
L27:         case ">":
L28:           return c > 0;
L29:         case "<":
L30:           return c < 0;
L31:         default:
L32:           return c === 0;
L33:       }
L34:     });
L35: }
