    const loaded = await loadProject(p.ctx.dir);
    if (loaded.project) {
      p.ctx.project = loaded.project;
      p.ctx.defs = loaded;
      p.sourcePolling?.wake();
    }
    if (loaded.errors.length) this.projectErrors.set(id, loaded.errors);
