    const a = this.account(id);
    if (a.kind === "forge") {
      const ok = await identityOk(a);
      if (ok) await this.releaseAuth(id, null);
      return ok ? "logged_in" : "logged_out";
    }
    if (a.kind === "service") return "unknown";
